pm.test("Woreda-wide assignment and translations", function () {
  pm.expect(data.assignmentMode).to.eql("Woreda");
  pm.expect(data.assignedDaIds || []).to.be.an("array").that.is.empty;
  const translated = (data.parameters || []).find(p => p.id === "p4") || {};
  pm.expect(translated.translations).to.include.keys("Amharic", "Afaan Oromoo");
  pm.expect(translated.prompt).to.be.a("string").that.is.not.empty;
});

